PRAGMA foreign_keys=ON;
DROP TABLE IF EXISTS TimeEntries; DROP TABLE IF EXISTS Timesheets; DROP TABLE IF EXISTS ProjectAssignments;
DROP TABLE IF EXISTS WorkItems; DROP TABLE IF EXISTS Projects; DROP TABLE IF EXISTS Clients; DROP TABLE IF EXISTS PayPeriods;
DROP TABLE IF EXISTS UserAccounts; DROP TABLE IF EXISTS Employees; DROP TABLE IF EXISTS Roles; DROP TABLE IF EXISTS Departments;

CREATE TABLE Departments(DepartmentId INTEGER PRIMARY KEY,DepartmentName TEXT NOT NULL UNIQUE,CostCentreCode TEXT NOT NULL UNIQUE,IsActive INTEGER NOT NULL DEFAULT 1);
CREATE TABLE Roles(RoleId INTEGER PRIMARY KEY,RoleName TEXT NOT NULL UNIQUE,DefaultHourlyRate REAL NOT NULL);
CREATE TABLE Employees(EmployeeId INTEGER PRIMARY KEY,EmployeeNumber TEXT NOT NULL UNIQUE,FirstName TEXT NOT NULL,LastName TEXT NOT NULL,PreferredName TEXT,Email TEXT,DepartmentId INTEGER NOT NULL REFERENCES Departments,RoleId INTEGER NOT NULL REFERENCES Roles,ManagerEmployeeId INTEGER REFERENCES Employees,HireDate TEXT NOT NULL,TerminationDate TEXT,AnnualSalary REAL,IsActive INTEGER NOT NULL DEFAULT 1);
CREATE TABLE UserAccounts(UserAccountId INTEGER PRIMARY KEY,EmployeeId INTEGER NOT NULL UNIQUE REFERENCES Employees,UserName TEXT NOT NULL UNIQUE,LastLoginAt TEXT,IsLocked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE Clients(ClientId INTEGER PRIMARY KEY,ClientCode TEXT NOT NULL UNIQUE,ClientName TEXT NOT NULL,Status TEXT NOT NULL,BillingEmail TEXT,CreatedAt TEXT NOT NULL);
CREATE TABLE Projects(ProjectId INTEGER PRIMARY KEY,ClientId INTEGER NOT NULL REFERENCES Clients,ProjectCode TEXT NOT NULL UNIQUE,ProjectName TEXT NOT NULL,Status TEXT NOT NULL,StartDate TEXT NOT NULL,EndDate TEXT,BudgetHours REAL,IsBillable INTEGER NOT NULL);
CREATE TABLE ProjectAssignments(ProjectId INTEGER NOT NULL REFERENCES Projects,EmployeeId INTEGER NOT NULL REFERENCES Employees,AssignedAt TEXT NOT NULL,AllocationPercent INTEGER,PRIMARY KEY(ProjectId,EmployeeId));
CREATE TABLE WorkItems(WorkItemId INTEGER PRIMARY KEY,ProjectId INTEGER NOT NULL REFERENCES Projects,Title TEXT NOT NULL,Status TEXT NOT NULL,Priority TEXT NOT NULL,AssignedEmployeeId INTEGER REFERENCES Employees,CreatedAt TEXT NOT NULL,CompletedAt TEXT);
CREATE TABLE PayPeriods(PayPeriodId INTEGER PRIMARY KEY,PeriodName TEXT NOT NULL UNIQUE,StartDate TEXT NOT NULL,EndDate TEXT NOT NULL,PayDate TEXT NOT NULL,Status TEXT NOT NULL);
CREATE TABLE Timesheets(TimesheetId INTEGER PRIMARY KEY,EmployeeId INTEGER NOT NULL REFERENCES Employees,PayPeriodId INTEGER NOT NULL REFERENCES PayPeriods,Status TEXT NOT NULL,SubmittedAt TEXT,ApprovedAt TEXT,ApprovedByEmployeeId INTEGER REFERENCES Employees,UNIQUE(EmployeeId,PayPeriodId));
CREATE TABLE TimeEntries(TimeEntryId INTEGER PRIMARY KEY,TimesheetId INTEGER REFERENCES Timesheets,EmployeeId INTEGER NOT NULL REFERENCES Employees,ProjectId INTEGER NOT NULL REFERENCES Projects,WorkItemId INTEGER REFERENCES WorkItems,StartTime TEXT NOT NULL,EndTime TEXT,HoursWorked REAL,EntryStatus TEXT NOT NULL,IsBillable INTEGER NOT NULL,Notes TEXT,CreatedAt TEXT NOT NULL);
CREATE INDEX IX_TimeEntries_Employee_StartTime ON TimeEntries(EmployeeId,StartTime);
CREATE INDEX IX_TimeEntries_Project_Status ON TimeEntries(ProjectId,EntryStatus);

